                <div style={{ fontSize: 22, color: COLORS.grey, fontFamily: FONT_FAMILY, fontWeight: FONT_WEIGHT_NORMAL }}>Manual work</div>
              </div>
            </div>
          </div>

          {/* Right: Competitive Landscape */}
          <div style={{ width: 1460, height: 700, background: COLORS.containerBg, border: `1px solid ${COLORS.containerBorder}`, borderRadius: 16, padding: 0, position: "relative", overflow: "hidden" }}>
            <Img src={MAP_IMAGE_SRC} style={{ width: "100%", height: "100%", objectFit: "cover", position: "absolute", top: 0, left: 0 }} />
            <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", background: "rgba(11, 18, 33, 0.4)" }} />

            <div style={{ position: "relative", width: "100%", height: "100%", padding: 40, display: "flex", flexDirection: "column" }}>
              <div style={{ fontSize: 24, color: COLORS.teal, letterSpacing: 3, fontWeight: FONT_WEIGHT_BOLD, marginBottom: 20, fontFamily: FONT_FAMILY }}>
                COMPETITIVE LANDSCAPE — LIVE VIEW
              </div>

              <div style={{ position: "relative", width: "100%", flex: 1 }}>
                {(() => {
                  const yourP = spring({ frame, fps, delay: 20, config: { damping: 200 } });
                  const pulse = 1 + 0.1 * Math.sin((frame / fps) * Math.PI * 2 * 0.6);
                  return (
                    <div style={{ position: "absolute", left: "25%", top: "45%", transform: `translate(-50%, -50%) scale(${interpolate(yourP, [0, 1], [0, pulse])})`, display: "flex", flexDirection: "column", alignItems: "center", opacity: yourP }}>
                      <div style={{ width: 48, height: 48, borderRadius: "50%", backgroundColor: COLORS.teal, boxShadow: "0 0 24px rgba(0,212,170,0.6)" }} />
                      <span style={{ fontSize: 20, color: COLORS.teal, fontWeight: FONT_WEIGHT_BOLD, marginTop: 8, whiteSpace: "nowrap", fontFamily: FONT_FAMILY }}>Your Location</span>
                    </div>
                  );
                })()}

                {COMPETITOR_DOTS.map((dot, i) => {
                  const dotP = spring({ frame, fps, delay: 30 + i * 8, config: { damping: 200 } });
                  const drift = Math.sin(((frame + i * 20) / fps) * Math.PI * 0.3) * 8;
                  return (
                    <div key={`comp-${i}`} style={{ position: "absolute", left: `${dot.x * 100}%`, top: `${dot.y * 100}%`, transform: `translate(-50%, -50%) translate(${drift}px, ${drift * 0.5}px) scale(${interpolate(dotP, [0, 1], [0, 1])})`, width: dot.size, height: dot.size, borderRadius: "50%", backgroundColor: dot.color, opacity: dotP, boxShadow: `0 0 10px ${dot.color}44` }} />
                  );
                })}

                <div style={{ position: "absolute", right: 0, bottom: 0, background: "rgba(0,212,170,0.1)", border: `1px solid ${COLORS.tealBorder}`, borderRadius: 20, padding: "8px 20px", fontSize: 22, color: COLORS.teal, fontWeight: FONT_WEIGHT_NORMAL, fontFamily: FONT_FAMILY }}>
                  Apr 2025
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

